// NEW_AUTHORED integer-foot kernel. Time remainder is not a physical fractional foot.
export function exactFoot(p,w,h){return Array.isArray(p)&&Object.getPrototypeOf(p)===Array.prototype&&p.length===2&&Reflect.ownKeys(p).length===3&&['0','1','length'].every(k=>Object.hasOwn(p,k)&&Object.hasOwn(Object.getOwnPropertyDescriptor(p,k),'value'))&&Number.isInteger(p[0])&&Number.isInteger(p[1])&&p[0]>=0&&p[0]<w&&p[1]>=0&&p[1]<h;}
export class PostNativeWalker{
 constructor(input){this.input=input;this.x=input.spawn[0];this.y=input.spawn[1];this.facing='right';this.walk=0;this.moving=false;this.epoch=0;this.keys=new Set();this.focused=true;this.locked=false;this.remainderX=0;this.remainderY=0;}
 safe(x,y){return exactFoot([x,y],this.input.width,this.input.height)&&!!this.input.safe49Rows[y]?.some(([a,b])=>x>=a&&x<b);}
 move(dx,dy,{revision=this.input.revision,epoch=this.epoch}={}){this.moving=false;if(revision!==this.input.revision||epoch!==this.epoch||this.locked||!this.focused||!Number.isInteger(dx)||!Number.isInteger(dy)||(dx&&dy)||Math.abs(dx||dy)>240||!this.safe(this.x,this.y))return {moved:0,reason:'INPUT_REJECTED'};if(dx)this.facing=dx>0?'right':'left';if(dy)this.facing=dy>0?'down':'up';const length=Math.abs(dx||dy);let moved=0;for(;moved<length;moved++){const x=this.x+(dx?Math.sign(dx):0),y=this.y+(dy?Math.sign(dy):0);if(!this.safe(x,y))break;this.x=x;this.y=y;}this.walk+=moved;this.moving=moved>0;return {moved,reason:moved===length?'OK':'COLLISION_OR_UNKNOWN'};}
 canRead(anchor){return exactFoot(anchor,this.input.width,this.input.height)&&Math.abs(this.x-anchor[0])+Math.abs(this.y-anchor[1])<=48;}
 stop(){this.epoch++;this.keys.clear();this.moving=false;this.remainderX=0;this.remainderY=0;}setFocus(v){this.focused=v;this.stop();}setLocked(v){if(v!==this.locked){this.locked=v;this.stop();}}key(k,v){if(!this.focused||this.locked)return false;if(v)this.keys.add(k);else this.keys.delete(k);return true;}
 tick(dt){if(!Number.isFinite(dt)||dt<0||dt>2){this.stop();return;}if(this.locked||!this.focused){this.moving=false;return;}const dir={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[[...this.keys].at(-1)];if(!dir){this.moving=false;return;}const axis=dir[0]?'remainderX':'remainderY',other=dir[0]?'remainderY':'remainderX';this[other]=0;this[axis]+=120*dt*(dir[0]||dir[1]);const sign=Math.sign(this[axis]);const steps=sign*Math.floor(Math.abs(this[axis])+1e-9);this[axis]-=steps;if(Math.abs(this[axis])<1e-9)this[axis]=0;if(!steps){this.moving=false;return;}const result=this.move(dir[0]?steps:0,dir[1]?steps:0);if(result.reason!=='OK')this[axis]=0;}
}
